<template><div class="pro-page page-animate"><div class="wrap"><section class="football-hero page-hero-compact"><div><span class="eyebrow">Multi-match selections</span><h1>Acca Tips</h1><p>Build an accumulator from this week's strongest published selections. These combinations are a convenience view, not a guarantee.</p></div><RouterLink to="/predictions" class="hero-action">Browse all picks →</RouterLink></section><div v-if="loading" class="grid3"><div v-for="n in 3" :key="n" class="tip-skeleton"></div></div><div v-else class="acca-grid"><article v-for="(acca,i) in accas" :key="i" class="pro-panel acca-card"><div class="acca-head"><div><span class="eyebrow">ACCUMULATOR {{ i+1 }}</span><h2>{{ acca.legs.length }} legs</h2></div><strong>{{ acca.odds.toFixed(2) }}</strong></div><div v-for="p in acca.legs" :key="p._id" class="acca-leg"><span>{{ p.matchId?.homeTeamId?.shortName||p.fixture }}</span><b>{{ p.prediction }}</b><small>@ {{ Number(p.odds||0).toFixed(2) }}</small></div><RouterLink to="/predictions" class="btn">Research selections</RouterLink></article><div v-if="!accas.length" class="pro-panel empty">No suitable published selections are available to build an acca yet.</div></div></div></div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {RouterLink} from 'vue-router';import {api} from '../services/api';const data=ref<any[]>([]),loading=ref(true);const accas=computed(()=>{const base=data.value.filter(p=>!p.isPremium&&p.prediction&&!/draw|home win|away win/i.test(p.prediction)).slice(0,9);const out:any[]=[];for(let i=0;i<base.length;i+=3){const legs=base.slice(i,i+3);if(legs.length===3)out.push({legs,odds:legs.reduce((x:number,p:any)=>x*Number(p.odds||1),1)})}return out.slice(0,3)});onMounted(async()=>{try{data.value=(await api.get('/predictions?limit=50&horizon=weekly&refresh=1')).data||[]}finally{loading.value=false}})</script>
